<template><AppLayout><div class="mx-auto max-w-6xl space-y-6">
  <header class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold">{{ t('adminMarketplace.policies') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('adminMarketplace.policyScope') }}</p><p class="mt-2 text-sm">{{ t('adminMarketplace.version') }} {{ currentVersion }} <span v-if="publishedAt"> · {{ publishedAt }}</span></p></div><button class="btn btn-secondary" :disabled="loading || busy" @click="refresh">{{ t('common.refresh') }}</button></header>
  <p v-if="error" role="alert" class="text-red-600">{{ error }}</p><p v-if="loading">{{ t('common.loading') }}</p>
  <form v-else @submit.prevent="confirming = true"><fieldset :disabled="busy" class="space-y-6">
    <section class="card space-y-4 p-5"><h2 class="text-lg font-semibold">{{ t('adminMarketplace.commercialTerms') }}</h2><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label v-for="field in termFields" :key="field.key" class="block text-sm">{{ t(`adminMarketplace.${field.key}`) }}<input v-model="terms[field.key]" class="input mt-1" :inputmode="field.key === 'minimum_payout_usd' ? 'decimal' : 'numeric'" required /></label></div></section>
    <section class="card space-y-4 p-5"><div class="flex flex-wrap items-end gap-3"><h2 class="mr-auto text-lg font-semibold">{{ t('adminMarketplace.priceBook') }}</h2><label class="text-sm">{{ t('adminMarketplace.group') }}<select v-model.number="groupId" class="input mt-1"><option :value="0">{{ t('adminMarketplace.chooseGroup') }}</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{ group.name }} · {{ group.platform }}</option></select></label><button type="button" class="btn btn-secondary" :disabled="!groupId" @click="addGroup">{{ t('adminMarketplace.addGroup') }}</button></div>
      <p v-if="!groups.length" class="text-sm text-gray-500">{{ t('adminMarketplace.noGroups') }}</p>
      <article v-for="(group, gi) in groups" :key="group.group_id" class="space-y-4 rounded-xl border border-gray-200 p-4 dark:border-dark-600"><div class="flex flex-wrap items-center gap-3"><h3 class="mr-auto font-semibold">{{ group.name }} · {{ group.platform }}</h3><label class="text-sm">{{ t('adminMarketplace.protocol') }} <select v-model="group.protocol" class="input"><option value="chat_completions">chat_completions</option><option value="responses">responses</option></select></label><button type="button" class="btn btn-secondary btn-sm" @click="groups.splice(gi, 1)">{{ t('adminMarketplace.remove') }}</button></div>
        <div v-for="(model, mi) in group.models" :key="mi" class="space-y-3 border-t border-gray-200 pt-4 dark:border-dark-600"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><label v-for="field in modelFields" :key="field.key" class="text-sm">{{ t(`adminMarketplace.${field.key}`) }}<input :value="model[field.key]" class="input mt-1" required @input="setModelField(model, field.key, ($event.target as HTMLInputElement).value)" /></label></div><div v-for="(tier, ti) in model.tiers" :key="ti" class="grid gap-3 rounded-lg bg-gray-50 p-3 dark:bg-dark-900 sm:grid-cols-2 lg:grid-cols-6"><label v-for="field in tierFields" :key="field" class="text-sm">{{ t(`adminMarketplace.${field}`) }}<input :value="tier[field]" class="input mt-1" inputmode="decimal" required @input="setTierField(tier, field, ($event.target as HTMLInputElement).value)" /></label><button type="button" class="btn btn-secondary self-end" :disabled="model.tiers.length === 1" @click="model.tiers.splice(ti, 1)">{{ t('adminMarketplace.remove') }}</button></div><div class="flex flex-wrap gap-2"><button type="button" class="btn btn-secondary btn-sm" @click="model.tiers.push(blankTier())">{{ t('adminMarketplace.addTier') }}</button><button type="button" class="btn btn-secondary btn-sm" @click="group.models.splice(mi, 1)">{{ t('adminMarketplace.removeModel') }}</button></div></div><button type="button" class="btn btn-secondary btn-sm" @click="group.models.push(blankModel())">{{ t('adminMarketplace.addModel') }}</button>
      </article>
    </section><p v-if="validationError" role="alert" class="text-red-600">{{ validationError }}</p><button class="btn btn-primary" :disabled="busy">{{ t('adminMarketplace.publish') }}</button>
  </fieldset></form>
  <BaseDialog :show="confirming" :title="t('adminMarketplace.publish')" @close="!busy && (confirming = false)"><p>{{ t('adminMarketplace.publishConfirm') }}</p><p v-if="validationError" role="alert" class="mt-3 text-red-600">{{ validationError }}</p><template #footer><button class="btn btn-secondary" :disabled="busy" @click="confirming = false">{{ t('common.cancel') }}</button><button class="btn btn-primary" :disabled="busy" @click="publish">{{ t('adminMarketplace.publish') }}</button></template></BaseDialog><TotpStepUpDialog :controller="stepUp" />
</div></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useWorkModeStore } from '@/stores/workMode'
import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
import * as groupAPI from '@/api/admin/groups'
import { get, post, type BookGroup, type PolicyResult, type Tier, type Model } from '@/api/admin/marketplace'
import { validPrice } from './adminState'
import type { AdminGroup } from '@/types'
const { t } = useI18n(); const stepUp = useStepUp(); const workMode = useWorkModeStore()
const loading = ref(true), busy = ref(false), confirming = ref(false), error = ref(''), validationError = ref(''), currentVersion = ref(0), publishedAt = ref(''), groupId = ref(0), availableGroups = ref<AdminGroup[]>([]), groups = ref<BookGroup[]>([])
const terms = reactive({ fee_bps: '', hold_hours: '', max_supplier_concurrency: '', minimum_payout_usd: '' })
const snapshot = computed(() => JSON.stringify({ terms, groups: groups.value }))
const savedSnapshot = ref(snapshot.value)
watch([snapshot, loading], () => { workMode.dirty = !loading.value && snapshot.value !== savedSnapshot.value })
onBeforeRouteLeave(() => !busy.value)
function beforeUnload(event: BeforeUnloadEvent) { if (workMode.dirty || busy.value) { event.preventDefault(); event.returnValue = '' } }
async function refresh() { if (!busy.value && await workMode.confirmLeave()) await load() }
const termFields = [{ key: 'fee_bps' }, { key: 'hold_hours' }, { key: 'max_supplier_concurrency' }, { key: 'minimum_payout_usd' }] as const
const modelFields = [{ key: 'public_model' }, { key: 'actual_model' }, { key: 'context_limit' }, { key: 'max_output_tokens' }, { key: 'rate_multiplier' }] as const
const tierFields = ['from_tokens', 'input_per_million', 'output_per_million', 'cache_read_per_million', 'cache_write_per_million'] as const
const blankTier = (): Tier => ({ from_tokens: 0, input_per_million: '', output_per_million: '', cache_read_per_million: '', cache_write_per_million: '' })
const blankModel = (): Model => ({ public_model: '', actual_model: '', context_limit: 0, max_output_tokens: 0, rate_multiplier: '', tiers: [blankTier()] })
async function load() { loading.value = true; error.value = ''; try { const [result, allGroups] = await Promise.all([get<PolicyResult>('policies'), groupAPI.getAll()]); availableGroups.value = allGroups; currentVersion.value = result.version; publishedAt.value = result.published_at; groups.value = structuredClone(result.book?.groups || []); if (result.version > 0 && result.policy) { for (const field of termFields) terms[field.key] = String(result.policy[field.key]) } savedSnapshot.value = snapshot.value } catch (e: any) { error.value = e?.message || t('adminMarketplace.loadError') } finally { loading.value = false } }
function setModelField(model: Model, field: typeof modelFields[number]['key'], value: string) { if (field === 'context_limit' || field === 'max_output_tokens') model[field] = value === '' ? 0 : Number(value); else model[field] = value }
function setTierField(tier: Tier, field: typeof tierFields[number], value: string) { if (field === 'from_tokens') tier.from_tokens = value === '' ? -1 : Number(value); else tier[field] = value }
function addGroup() { const group = availableGroups.value.find(g => g.id === groupId.value); if (group && !groups.value.some(g => g.group_id === group.id)) groups.value.push({ group_id: group.id, name: group.name, platform: group.platform, protocol: 'chat_completions', models: [] }); groupId.value = 0 }
function valid() { const integer = (s: unknown, min: number, max = Number.MAX_SAFE_INTEGER) => /^\d+$/.test(String(s)) && Number(s) >= min && Number(s) <= max; return integer(terms.fee_bps, 0, 10000) && integer(terms.hold_hours, 0) && integer(terms.max_supplier_concurrency, 1) && /^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(terms.minimum_payout_usd) && groups.value.length > 0 && groups.value.every(g => g.models.length > 0 && g.models.every(m => m.public_model.trim() && m.actual_model.trim() && integer(m.context_limit, 1, 4000000) && integer(m.max_output_tokens, 1, Number(m.context_limit)) && validPrice(m.rate_multiplier) && m.tiers.length > 0 && m.tiers.every((tier, index) => integer(tier.from_tokens, 0) && (index === 0 ? Number(tier.from_tokens) === 0 : Number(tier.from_tokens) > Number(m.tiers[index - 1].from_tokens)) && tierFields.slice(1).every(f => validPrice(String(tier[f])))))) }
async function publish() { if (busy.value) return; if (!valid()) { validationError.value = t('adminMarketplace.invalidPolicy'); return } busy.value = true; validationError.value = ''; try { await stepUp.run(() => post('policies', { policy: { fee_bps: Number(terms.fee_bps), hold_hours: Number(terms.hold_hours), max_supplier_concurrency: Number(terms.max_supplier_concurrency), minimum_payout_usd: terms.minimum_payout_usd }, book: { groups: groups.value } })); confirming.value = false; await load() } catch (e: any) { if (!isStepUpCancelled(e)) validationError.value = e?.message || t('adminMarketplace.actionError') } finally { busy.value = false } }
onMounted(() => { void load(); window.addEventListener('beforeunload', beforeUnload) })
onUnmounted(() => { window.removeEventListener('beforeunload', beforeUnload); workMode.dirty = false })
</script>
